-- DEPLOY005_BASELINE_GUARD; target selected and verified by the remote orchestrator.
SET LOCAL search_path=public;
LOCK TABLE public.chest_operations,public.equipped_items,public.guild_activity_log,public.guild_chat_messages,public.guild_chat_moderation_log,public.guild_chat_reads,public.guild_chat_reports,public.guild_invites,public.guild_join_requests,public.guild_members,public.guild_mission_progress,public.guild_missions,public.guild_reward_claims,public.guilds,public.inventory,public.profiles,public.traveler_chests,public.traveler_stats,public.travelers,public.wallets IN SHARE ROW EXCLUSIVE MODE;
DO $guard$ DECLARE got record; BEGIN
IF to_regnamespace('economy_private') IS NOT NULL OR to_regnamespace('story_private') IS NOT NULL OR to_regnamespace('guild_ops') IS NOT NULL OR to_regnamespace('ebd_ops') IS NOT NULL OR to_regclass('public.guild_lessons') IS NOT NULL THEN RAISE EXCEPTION 'DEPLOY005 target already changed'; END IF;
SELECT * INTO got FROM (SELECT md5((catalog->'functions')::text) AS functions_md5,md5((catalog->'columns')::text) AS columns_md5,md5((catalog->'policies')::text) AS policies_md5,md5((catalog->'triggers')::text) AS triggers_md5 FROM (SELECT jsonb_build_object('functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','guild_chat_private') AND p.prokind='f'),'columns',(SELECT jsonb_agg(jsonb_build_object('table',table_name,'name',column_name,'type',data_type,'nullable',is_nullable,'default',column_default) ORDER BY table_name,ordinal_position) FROM information_schema.columns WHERE table_schema='public'),'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname) FROM pg_policies p WHERE schemaname IN ('public','guild_chat_private')),'triggers',(SELECT jsonb_agg(pg_get_triggerdef(t.oid) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal))) q(catalog)) fingerprints;
IF got.functions_md5 IS DISTINCT FROM '6313ebf10f2534d87f93b13864afee36' OR got.columns_md5 IS DISTINCT FROM '1b2b9518c86a34300fe6430486d93a3e' OR got.policies_md5 IS DISTINCT FROM '5fed1e3334b89ceb2a108726324d2c61' OR got.triggers_md5 IS DISTINCT FROM '07f657302f931ece2757dbf3982c02cc' THEN RAISE EXCEPTION 'DEPLOY005 live baseline drift; refuse application'; END IF;
END $guard$;
